(() => {
  const closeAddress = Module.getGlobalExportByName('close');
  Interceptor.attach(closeAddress, {
    onEnter(args) {
      this.descriptor = args[0].toInt32();
      this.cloaked = Cloak.hasFileDescriptor(this.descriptor);
      send({operation: 'close-enter', pid: Process.id,
        threadId: Process.getCurrentThreadId(), descriptor: this.descriptor,
        cloaked: this.cloaked, caller: this.returnAddress.toString()});
    },
    onLeave(result) {
      send({operation: 'close-return', pid: Process.id,
        descriptor: this.descriptor, cloaked: this.cloaked,
        result: result.toInt32(), nativeError: this.errno});
    }
  });

  for (const name of ['execv', 'execve', '__execve']) {
    const address = Module.findGlobalExportByName(name);
    if (address === null) {
      send({operation: 'symbol-absent', name});
      continue;
    }
    Interceptor.attach(address, {
      onEnter(args) {
        send({operation: 'exec-enter', pid: Process.id,
          threadId: Process.getCurrentThreadId(), name,
          path: args[0].readUtf8String(), caller: this.returnAddress.toString()});
      },
      onLeave(result) {
        send({operation: 'exec-return', pid: Process.id, name,
          result: result.toInt32(), nativeError: this.errno});
      }
    });
  }
  send({operation: 'observer-ready', pid: Process.id,
    closeAddress: closeAddress.toString()});
})();

